:root{--ink:#221e35;--muted:#888397;--cream:#f6f2ec;--paper:#fffdfa;--plum:#6f4a79;--rose:#c47d92;--gold:#d8b77c;--line:#eae5e2;--serif:'Playfair Display',Georgia,serif;--sans:'DM Sans',Arial,sans-serif}*{box-sizing:border-box}body{margin:0;background:#17152c;color:var(--ink);font-family:var(--sans);min-height:100vh}.app-shell{max-width:1600px;margin:0 auto;padding:0 40px}.topbar{height:82px;display:flex;align-items:center;justify-content:space-between;color:#f8f3f5;border-bottom:1px solid #ffffff1b}.wordmark{display:flex;align-items:center;gap:12px;color:#fff;text-decoration:none;font-size:12px;letter-spacing:.2em;font-weight:700}.wordmark i{font-style:normal;color:#d3b8c5;font-weight:400}.brand-mark{color:#d8b77c;font-size:21px}.top-meta{display:flex;align-items:center;gap:29px;font-size:9px;letter-spacing:.16em;color:#c5bdcc}.status-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#a6c29d;margin-right:8px;box-shadow:0 0 8px #a6c29d}.sound-button{background:none;border:0;color:#e4d7e2;font:600 10px var(--sans);letter-spacing:.12em;cursor:pointer}.sound-button span{color:#968da0;margin-left:4px}.game-layout{display:grid;grid-template-columns:minmax(0,1.22fr) minmax(420px,.78fr);gap:20px;height:min(810px,calc(100vh - 130px));min-height:650px;padding:20px 0}.stage{position:relative;overflow:hidden;border-radius:5px;background:linear-gradient(180deg,#31314d 0%,#62516f 42%,#c47d92 76%,#ecb79c 100%);color:white;isolation:isolate}.stage:before{content:"";position:absolute;inset:0;background:linear-gradient(110deg,#16172d55,transparent 58%),linear-gradient(0deg,#15142999,transparent 48%);z-index:-1}.sky-glow{position:absolute;width:480px;height:480px;border-radius:50%;top:9%;left:42%;background:radial-gradient(circle,#f9c5b62a 0,#e995a514 35%,transparent 69%);filter:blur(8px)}.moon{position:absolute;width:80px;height:80px;border-radius:50%;top:15%;right:19%;background:#fff0d9;box-shadow:0 0 35px #ffe4c866,0 0 90px #f4cbdd35;opacity:.88}.scene-stars{position:absolute;inset:0;opacity:.6;background-image:radial-gradient(1px 1px at 11% 22%,#fff 70%,transparent),radial-gradient(1px 1px at 27% 13%,#fff 70%,transparent),radial-gradient(1.5px 1.5px at 52% 22%,#fff 70%,transparent),radial-gradient(1px 1px at 75% 11%,#fff 70%,transparent),radial-gradient(1px 1px at 83% 36%,#fff 70%,transparent),radial-gradient(1px 1px at 38% 38%,#fff 70%,transparent),radial-gradient(1px 1px at 91% 23%,#fff 70%,transparent)}.scene-label{position:absolute;z-index:5;top:27px;left:30px;right:30px;display:flex;gap:11px;align-items:center;font-size:8px;letter-spacing:.2em;color:#f1dce5}.chapter-symbol{font-size:14px;color:#f1d49e}.scene-line{height:1px;width:28px;background:#ffffff65}.scene-art{position:absolute;inset:0;z-index:1;overflow:hidden}.stage-caption{position:absolute;left:8%;top:37%;z-index:2;text-shadow:0 2px 15px #16142955;transition:opacity .3s}.stage-caption span{display:block;color:#f4d7ce;font-size:9px;letter-spacing:.2em;margin-bottom:18px}.stage-caption strong{font:500 clamp(28px,3.8vw,52px)/1.14 var(--serif);letter-spacing:-.03em}.scene-vignette{position:absolute;z-index:3;inset:0;pointer-events:none;background:linear-gradient(0deg,#17152ccc 0%,transparent 34%),linear-gradient(90deg,#18162b15,transparent 70%)}.stage-footer{position:absolute;z-index:5;bottom:22px;left:30px;right:30px;display:flex;justify-content:space-between;font-size:8px;letter-spacing:.17em;color:#ecdae0}.play-panel{border-radius:5px;background:var(--paper);overflow:hidden;position:relative}.panel-scroll{height:100%;overflow:auto;padding:36px 39px 28px;scrollbar-width:thin;scrollbar-color:#d6c9d2 transparent}.eyebrow{font-size:9px;letter-spacing:.2em;font-weight:700;color:#9c7385;text-transform:uppercase}.panel-title{font:600 31px/1.17 var(--serif);letter-spacing:-.03em;color:#262137;margin:10px 0 12px}.lead{font-size:13px;line-height:1.75;color:#777183;margin:0 0 22px}.ornament{display:flex;align-items:center;gap:10px;color:#c5a36d;font-size:11px;margin:21px 0}.ornament:before,.ornament:after{content:"";height:1px;background:#e8dfd8;flex:1}.section-label{font-size:9px;letter-spacing:.15em;font-weight:700;color:#756b7d;text-transform:uppercase;margin:20px 0 10px}.origin-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.choice-card{position:relative;border:1px solid #e8e2e4;background:#fff;border-radius:4px;text-align:left;padding:13px 14px;cursor:pointer;transition:.2s;color:var(--ink);min-height:91px}.choice-card:hover{border-color:#b995a5;transform:translateY(-1px)}.choice-card.selected{border-color:#94708a;background:#fbf6f8;box-shadow:0 0 0 1px #94708a inset}.choice-icon{display:block;color:#a47791;font-size:17px;margin-bottom:6px}.choice-card b{font:600 14px var(--serif);display:block}.choice-card small{display:block;font:10px/1.5 var(--sans);color:#898292;margin-top:3px}.form-row{display:flex;gap:12px}.field{display:flex;flex-direction:column;gap:7px;flex:1;min-width:0}.field label{font-size:9px;letter-spacing:.12em;color:#7e7585;text-transform:uppercase;font-weight:700}.field input,.field select{height:39px;border:1px solid #e7e1e3;border-radius:3px;padding:0 11px;background:#fff;font:12px var(--sans);color:#3e384a;outline:none}.field input:focus,.field select:focus{border-color:#a47b92;box-shadow:0 0 0 2px #a47b9218}.creator-block{border-top:1px solid #eee8e6;margin-top:19px;padding-top:5px}.appearance-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px 10px}.color-options{display:flex;align-items:center;gap:7px;height:31px}.swatch{width:20px;height:20px;border:2px solid white;box-shadow:0 0 0 1px #ddd;border-radius:50%;padding:0;cursor:pointer}.swatch.selected{box-shadow:0 0 0 1.5px #6f4a79,0 0 0 3px #fff}.select-mini{height:34px!important;padding:0 8px!important;font-size:11px!important}.creator-foot{display:flex;align-items:center;gap:9px;color:#898292;font-size:10px;line-height:1.45;margin:17px 0 19px}.mini-avatar{width:38px;height:38px;border-radius:50%;background:linear-gradient(#ead5d6,#e4b7aa);display:grid;place-items:center;overflow:hidden;border:2px solid #f5e8e5}.mini-avatar svg{height:47px;width:38px;transform:translateY(6px)}.button-primary,.button-secondary{width:100%;height:48px;border:0;border-radius:3px;background:#614b6c;color:white;font:700 10px var(--sans);letter-spacing:.15em;text-transform:uppercase;cursor:pointer;transition:.2s}.button-primary:hover{background:#755b7f;transform:translateY(-1px);box-shadow:0 7px 20px #614b6c2b}.button-primary span{color:#e1c896;font-size:14px;margin-left:8px}.button-secondary{background:transparent;border:1px solid #dcd1da;color:#74667a;height:40px}.button-secondary:hover{background:#faf5f7}.scene-kicker{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding-bottom:14px;margin-bottom:23px}.chapter-count{font-size:9px;color:#a39ba8;letter-spacing:.1em}.story-text{font:16px/1.8 var(--serif);color:#4b4555;margin:0 0 20px}.story-text em{color:#805e79}.speaker{font-size:9px;color:#a2768d;letter-spacing:.16em;text-transform:uppercase;font-weight:700;margin-bottom:8px}.dialogue{background:#f8f3f3;border-left:2px solid #bd8da1;padding:13px 15px;color:#65596a;font:13px/1.65 var(--serif);margin-bottom:20px}.option-list{display:flex;flex-direction:column;gap:9px;margin:15px 0 20px}.story-choice{border:1px solid #e8e0e2;background:white;text-align:left;padding:13px 15px;border-radius:3px;cursor:pointer;color:#393347;transition:.18s;display:flex;align-items:center;gap:12px}.story-choice:hover{border-color:#ae8599;background:#fcf8fa;transform:translateX(2px)}.choice-number{height:23px;width:23px;flex:none;border:1px solid #dfd3db;border-radius:50%;display:grid;place-items:center;color:#99778d;font-size:10px}.story-choice b{font:500 13px/1.45 var(--serif)}.story-choice small{display:block;font:10px var(--sans);color:#928a99;margin-top:3px}.route-cards{display:grid;grid-template-columns:1fr;gap:9px;margin:15px 0 20px}.route-card{padding:10px;display:flex;align-items:center;gap:12px;background:white;border:1px solid #e9e2e4;text-align:left;cursor:pointer;border-radius:3px;transition:.2s}.route-card:hover{border-color:#af899e;background:#fcf8fa;transform:translateY(-1px)}.route-avatar{width:54px;height:65px;flex:none;position:relative;border-radius:3px;overflow:hidden;background:linear-gradient(#d5d4e4,#85768e)}.route-avatar svg{height:88px;width:64px;position:absolute;left:-5px;bottom:-9px}.route-info{flex:1}.route-info b{font:600 16px var(--serif);display:block}.route-info small{color:#8f8796;font-size:10px;display:block;margin-top:4px}.route-tag{font-size:8px;letter-spacing:.1em;color:#9f738a;text-transform:uppercase;white-space:nowrap}.affinity{height:3px;background:#eee8ec;margin-top:8px;border-radius:3px;overflow:hidden}.affinity span{height:100%;display:block;background:linear-gradient(90deg,#c59aaa,#e1c384);transition:width .4s}.choice-note{text-align:center;color:#9b93a0;font-size:10px;line-height:1.5;margin:12px 0}.ending-card{background:linear-gradient(135deg,#f8eff1,#f7f3ed);border:1px solid #eee1e1;padding:19px;border-radius:4px;margin:18px 0}.ending-icon{font-size:25px;color:#ae8296}.ending-card h3{font:600 22px var(--serif);margin:7px 0}.ending-card p{color:#787181;font-size:12px;line-height:1.65}.stats-row{display:flex;justify-content:space-between;color:#9a919d;font-size:9px;letter-spacing:.1em;margin:19px 0}.site-footer{height:28px;display:flex;align-items:center;justify-content:space-between;color:#aaa2b0;font-size:8px;letter-spacing:.14em}.toast{position:fixed;bottom:25px;left:50%;transform:translate(-50%,20px);background:#29253d;color:white;padding:11px 18px;font-size:11px;border-radius:3px;opacity:0;pointer-events:none;transition:.25s;z-index:99;box-shadow:0 8px 25px #0003}.toast.show{opacity:1;transform:translate(-50%,0)}
/* Scene illustration */
.scene-art .city{position:absolute;bottom:0;left:0;right:0;height:32%;background:linear-gradient(0deg,#24243c,#42405b);clip-path:polygon(0 42%,7% 42%,7% 25%,12% 25%,12% 51%,17% 51%,17% 15%,22% 15%,22% 43%,27% 43%,27% 30%,33% 30%,33% 57%,38% 57%,38% 6%,44% 6%,44% 48%,50% 48%,50% 27%,56% 27%,56% 55%,63% 55%,63% 18%,70% 18%,70% 42%,76% 42%,76% 9%,82% 9%,82% 47%,87% 47%,87% 29%,93% 29%,93% 45%,100% 45%,100% 100%,0 100%)}.scene-art .water{position:absolute;bottom:0;left:0;right:0;height:23%;background:linear-gradient(180deg,#56506eaa,#26253d);opacity:.9}.scene-art .water:after{content:"";position:absolute;inset:10% 0;background:repeating-linear-gradient(175deg,transparent 0 11px,#f6cfca1e 12px 13px,transparent 14px 27px)}.char-illustration{position:absolute;bottom:2%;height:69%;width:43%;z-index:2;filter:drop-shadow(0 12px 14px #20182d55);transition:all .5s}.char-illustration.left{left:18%}.char-illustration.right{left:51%;transform:scaleX(-1)}.char-illustration svg{width:100%;height:100%;overflow:visible}.character-shadow{position:absolute;bottom:7%;left:20%;width:60%;height:9%;background:#17152c44;border-radius:50%;filter:blur(15px)}.prologue-art .city{height:37%}.prologue-art .char-illustration{height:65%}.prologue-art .char-illustration.left{left:31%;width:44%}.night-scene{background:linear-gradient(180deg,#24243e 0%,#484765 49%,#b77f91 100%)}.library-scene{background:linear-gradient(180deg,#272338 0%,#584459 48%,#bd8b79 100%)}.garden-scene{background:linear-gradient(180deg,#1d3040 0%,#526c70 52%,#cf9b86 100%)}.library-scene .scene-art:before,.garden-scene .scene-art:before{content:"";position:absolute;inset:12% 0 23%;opacity:.35;background:repeating-linear-gradient(90deg,transparent 0 9%,#211b3022 9.2% 10%,transparent 10.2% 18%)}
@media(max-width:980px){.app-shell{padding:0 22px}.game-layout{grid-template-columns:minmax(0,1fr) minmax(380px,.9fr);gap:14px}.panel-scroll{padding:28px 27px}.stage-caption{left:7%}.stage-caption strong{font-size:38px}}@media(max-width:760px){.app-shell{padding:0 12px}.topbar{height:62px}.top-meta .save-status{display:none}.game-layout{height:auto;min-height:0;display:flex;flex-direction:column;gap:12px;padding:12px 0}.stage{height:360px;flex:none}.play-panel{min-height:540px}.panel-scroll{padding:25px 22px 27px}.site-footer{font-size:7px}.site-footer span:nth-child(2){display:none}.stage-caption{top:35%}.stage-caption strong{font-size:38px}.moon{width:60px;height:60px}.char-illustration{height:70%}}@media(max-width:420px){.stage{height:310px}.panel-title{font-size:28px}.panel-scroll{padding:22px 17px}.origin-grid{gap:7px}.choice-card{padding:11px;min-height:87px}.appearance-grid{gap:10px 7px}.swatch{width:17px;height:17px}.form-row{gap:8px}.stage-caption strong{font-size:32px}.stage-caption span{font-size:7px}.site-footer{letter-spacing:.08em}}

const $ = (s) => document.querySelector(s);
const panel = $('#panel-scroll');
const stage = $('#stage');
const art = $('#scene-art');
const toast = $('#toast');
const defaults = {name:'', origin:'isekai', pronouns:'she / her', skin:'#e8b99f', eyes:'#7f8eab', hair:'#30283e', hairStyle:'soft waves', eyeShape:'almond'};
const avatar = {...defaults};
let screen = 'creator', route = null, chapter = 0, affinity = {aster:0, ren:0, soren:0}, originChoice='isekai';
let prologueChoice = '';
const leads = {
 aster:{id:'aster',name:'Aster Vale',role:'The star-reader',tag:'THE QUIET CONSTELLATION',hair:'#d8bd8c',skin:'#e8c2ad',eyes:'#83a3a4',style:'soft waves',coat:'#34455c',accent:'#ead6aa',scene:'night-scene',intro:'An astronomer who reads the future in a sky that no longer has stars. He trusts patterns more than people—until you arrive, carrying a constellation he has never seen.',quote:'“You appeared where the sky has a hole in it. Tell me… do you know what you are?”',places:['The observatory roof','The west watchtower','The starless dome'],moments:[['Tell him the truth about waking in another world.','A secret offered freely is still a kind of trust.'],['Ask what he wishes the stars would say.','For once, he answers without looking up.'],['Stay beside him in the silence.','Some silences feel more honest than words.']],final:['Let him choose the future, together.','Ask him to trust what cannot be measured.','Kiss him beneath the unfinished constellation.']},
 ren:{id:'ren',name:'Ren Amari',role:'The wandering blade',tag:'THE WAYWARD SWORD',hair:'#20232b',skin:'#d7a47f',eyes:'#bd725f',style:'tousled',coat:'#743f4d',accent:'#d5a176',scene:'garden-scene',intro:'A charming swordsman with a laugh too bright for a man who keeps leaving. Ren knows every road out of the capital, and none of the reasons to stay.',quote:'“You’ve got the look of someone who’s lost a whole world. Lucky for you, I’m very good at getting lost.”',places:['The lantern market','The old river bridge','The garden beyond the gate'],moments:[['Ask him to teach you the first move.','His hand pauses over yours, just a little too long.'],['Challenge his story about the road.','His grin slips. He appreciates that you noticed.'],['Tell him it’s okay to be afraid to stay.','For once, Ren has no clever answer.']],final:['Ask him to show you a road worth staying for.','Offer to walk beside him, wherever it leads.','Take his hand before he can make another joke.']},
 soren:{id:'soren',name:'Soren Lune',role:'The court alchemist',tag:'THE VELVET ALCHEMIST',hair:'#493448',skin:'#f0d4c2',eyes:'#8d789f',style:'long',coat:'#563f62',accent:'#d6af91',scene:'library-scene',intro:'A court alchemist whose beautiful hands can mend almost anything—except the strange fracture spreading through his own magic. He is all elegant manners and carefully guarded heart.',quote:'“Every impossible thing has a cause. And you, my dear, are the most impossible thing I have ever met.”',places:['The moonlit conservatory','The forbidden archive','The alchemy room after hours'],moments:[['Offer to help with his experiment.','He lets you hold the vial. That is its own kind of invitation.'],['Ask about the scar on his hand.','He tells you the part of the story he never tells.'],['Tell him he does not have to be useful to be wanted.','For a moment, all his composure disappears.']],final:['Choose the unknown with him, without a formula.','Promise to stay when the magic fades.','Let him see the parts of you that are still becoming.']]}
};
const skinColors=['#f5d9c5','#e8b99f','#d7a47f','#ae765f','#805344','#603f3b'];
const eyeColors=['#6c8c72','#83a3a4','#7f8eab','#8d789f','#bd725f','#46354d'];
const hairColors=['#30283e','#493448','#20232b','#a55e45','#d8bd8c','#d4c3b0'];
const hairStyles=['soft waves','tousled','long','bob','curly'];
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function hairSvg(style,color){
 const paths={
 'soft waves':`<path d="M77 179 Q60 62 148 47 Q250 42 228 177 L220 286 Q206 253 202 209 L198 145 Q165 173 109 153 Q99 214 82 268Z"/>`,
 'tousled':`<path d="M77 178 Q52 98 105 63 L90 40 L135 53 Q159 24 184 48 L211 39 L204 65 Q247 91 224 180 L212 252 L201 162 Q166 178 121 148 Q104 175 86 209Z"/>`,
 'long':`<path d="M77 174 Q62 53 148 47 Q241 45 226 179 L236 388 Q213 367 207 299 L200 150 Q166 172 109 151 Q99 260 79 369 L63 355Z"/>`,
 'bob':`<path d="M77 176 Q61 58 148 47 Q239 44 226 177 L217 257 Q204 238 202 150 Q163 176 108 150 Q101 212 83 255Z"/>`,
 'curly':`<path d="M72 178 Q51 151 66 124 Q48 89 83 76 Q80 39 118 51 Q139 22 161 48 Q194 23 207 59 Q248 63 228 108 Q247 142 224 176 L215 261 Q201 231 199 149 Q163 172 109 150 Q100 215 82 260Z"/><g fill="${color}"><circle cx="74" cy="125" r="23"/><circle cx="91" cy="79" r="24"/><circle cx="126" cy="54" r="23"/><circle cx="164" cy="52" r="24"/><circle cx="202" cy="76" r="23"/><circle cx="227" cy="124" r="23"/></g>`};
 return `<g fill="${color}">${paths[style]||paths['soft waves']}</g>`;
}
function personSvg(person,opts={}){
 const p={skin:person.skin||'#e8b99f',hair:person.hair||'#30283e',eyes:person.eyes||'#7f8eab',style:person.style||'soft waves',coat:person.coat||'#614c69',accent:person.accent||'#ddc59b',eyeShape:person.eyeShape||'almond'};
 const lashes=p.eyeShape==='round'?'M112 125 Q121 111 132 125 Q122 138 112 125 M169 125 Q180 111 190 125 Q180 138 169 125':'M111 126 Q122 117 133 126 Q122 136 111 126 M168 126 Q180 117 191 126 Q180 136 168 126';
 return `<svg viewBox="0 0 300 500" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Illustrated character portrait">
 <defs><linearGradient id="coat-${opts.id||'x'}" x1="0" x2="1" y1="0" y2="1"><stop stop-color="${p.coat}"/><stop offset="1" stop-color="#26263b"/></linearGradient><linearGradient id="face-${opts.id||'x'}" x1="0" x2=".8" y1="0" y2="1"><stop stop-color="${p.skin}"/><stop offset="1" stop-color="${p.skin}"/></linearGradient></defs>
 <path d="M18 500 Q22 381 62 337 Q91 307 122 300 L178 300 Q220 313 246 348 Q279 390 286 500Z" fill="url(#coat-${opts.id||'x'})"/>
 <path d="M117 296 L150 357 L185 296 L203 315 L178 500 L122 500 L96 315Z" fill="${p.accent}" opacity=".8"/>
 <path d="M126 270 L180 270 L186 316 L151 353 L115 315Z" fill="#d5a58e"/>
 <path d="M92 124 Q91 72 150 69 Q212 70 210 128 L202 215 Q194 274 152 283 Q108 276 98 216Z" fill="url(#face-${opts.id||'x'})"/>
 <path d="M94 167 Q80 142 84 125 Q94 110 102 139 M207 164 Q224 140 217 125 Q207 111 199 139" fill="${p.skin}"/>
 ${hairSvg(p.style,p.hair)}
 <path d="${lashes}" fill="#30263b"/><ellipse cx="122" cy="126" rx="4.2" ry="5.1" fill="${p.eyes}"/><ellipse cx="180" cy="126" rx="4.2" ry="5.1" fill="${p.eyes}"/><circle cx="123" cy="124" r="1.5" fill="white"/><circle cx="181" cy="124" r="1.5" fill="white"/>
 <path d="M148 137 Q143 164 151 165" fill="none" stroke="#b87970" stroke-width="2" stroke-linecap="round" opacity=".55"/><path d="M137 187 Q151 196 165 186" fill="none" stroke="#a95e67" stroke-width="2.3" stroke-linecap="round"/><path d="M135 205 Q151 211 166 204" fill="none" stroke="#d58e8c" stroke-width="2" opacity=".4"/>
 <path d="M114 104 Q124 98 136 103 M168 103 Q181 98 190 104" fill="none" stroke="${p.hair}" stroke-width="5" stroke-linecap="round"/>
 <path d="M74 344 Q91 322 116 314 L150 355 L184 314 Q213 321 231 346 L215 378 Q191 361 175 361 L150 388 L125 361 Q104 361 88 379Z" fill="${p.coat}"/>
 <path d="M150 358 L137 377 L150 468 L163 377Z" fill="${p.accent}" opacity=".72"/><circle cx="150" cy="396" r="4" fill="${p.accent}"/><circle cx="150" cy="423" r="3" fill="${p.accent}" opacity=".7"/>
 </svg>`;
}
function avatarSvg(){return personSvg({...avatar,coat:'#8a687b',accent:'#dfc7ae'},{id:'player'})}
function setStage({scene='night-scene',location='THE BETWEEN',time='A NEW BEGINNING',caption='',chars=[]}={}){
 stage.classList.remove('night-scene','library-scene','garden-scene','prologue-art'); stage.classList.add(scene);
 $('#scene-location').textContent=location.toUpperCase(); $('#scene-time').textContent=time.toUpperCase();
 $('#stage-caption').style.display=caption?'block':'none'; $('#stage-caption').innerHTML=caption?caption:'';
 art.innerHTML=`<div class="water"></div><div class="city"></div><div class="character-shadow"></div>${chars.map((c,i)=>`<div class="char-illustration ${chars.length===1?'left':i===0?'left':'right'}">${personSvg(c.person,{id:c.id})}</div>`).join('')}`;
}
function updatePreview(){
 const chars=Object.values(leads).map((p,i)=>({person:p,id:p.id}));
 setStage({scene:'night-scene',location:'A WORLD BETWEEN WORLDS',time:'YOUR STORY BEGINS HERE',chars,caption:'<span>AN ORIGINAL INTERACTIVE ROMANCE</span><strong>Somewhere between<br>who you were and who<br>you might become.</strong>'});
}
function swatches(colors,key){return `<div class="color-options">${colors.map(c=>`<button class="swatch ${avatar[key]===c?'selected':''}" data-key="${key}" data-color="${c}" style="background:${c}" aria-label="Select ${key} color ${c}" title="${c}"></button>`).join('')}</div>`}
function creator(){
 updatePreview();
 panel.innerHTML=`<div class="eyebrow">A romance written in the stars</div><h1 class="panel-title">Every great story<br>starts with a choice.</h1><p class="lead">A strange new world. Three unforgettable hearts. And a story that bends around the person you choose to be.</p>
 <div class="section-label">First, how did you get here?</div><div class="origin-grid">
 <button class="choice-card ${originChoice==='isekai'?'selected':''}" data-origin="isekai"><span class="choice-icon">✧</span><b>Another life</b><small>You woke in a world from a story you loved.</small></button>
 <button class="choice-card ${originChoice==='native'?'selected':''}" data-origin="native"><span class="choice-icon">☽</span><b>Born of this world</b><small>This is home. But something is changing.</small></button></div>
 <div class="creator-block"><div class="section-label">Your character</div><div class="form-row"><div class="field" style="flex:1.35"><label for="hero-name">Name</label><input id="hero-name" maxlength="18" placeholder="A name for your story" value="${esc(avatar.name)}"></div><div class="field"><label for="pronouns">Pronouns</label><select id="pronouns"><option ${avatar.pronouns==='she / her'?'selected':''}>she / her</option><option ${avatar.pronouns==='they / them'?'selected':''}>they / them</option><option ${avatar.pronouns==='he / him'?'selected':''}>he / him</option></select></div></div>
 <div class="section-label">Make them yours</div><div class="appearance-grid">
 <div class="field"><label>Skin tone</label>${swatches(skinColors,'skin')}</div>
 <div class="field"><label>Eye color</label>${swatches(eyeColors,'eyes')}</div>
 <div class="field"><label>Hair color</label>${swatches(hairColors,'hair')}</div>
 <div class="field"><label>Eye shape</label><select class="select-mini" id="eye-shape"><option>almond</option><option ${avatar.eyeShape==='round'?'selected':''}>round</option></select></div>
 <div class="field"><label>Hair style</label><select class="select-mini" id="hair-style">${hairStyles.map(x=>`<option ${avatar.hairStyle===x?'selected':''}>${x}</option>`).join('')}</select></div></div>
 <div class="creator-foot"><div class="mini-avatar">${avatarSvg()}</div><span>Your look is part of the story. You can change it any time before you begin.</span></div>
 <button class="button-primary" id="begin">STEP INTO THE STORY <span>→</span></button></div>`;
 panel.scrollTop=0;
 panel.querySelectorAll('[data-origin]').forEach(b=>b.onclick=()=>{originChoice=b.dataset.origin;creator()});
 panel.querySelectorAll('.swatch').forEach(b=>b.onclick=()=>{avatar[b.dataset.key]=b.dataset.color;creator()});
 $('#hero-name').oninput=e=>avatar.name=e.target.value;
 $('#pronouns').onchange=e=>avatar.pronouns=e.target.value;
 $('#eye-shape').onchange=e=>avatar.eyeShape=e.target.value;
 $('#hair-style').onchange=e=>{avatar.hairStyle=e.target.value;creator()};
 $('#begin').onclick=()=>{if(!avatar.name.trim())avatar.name='Mira';avatar.name=avatar.name.trim();screen='prologue';chapter=0;updatePreview();render()};
}

const prologueOptions=[
 {title:'Follow the silver moth into the city.',sub:'Some things are easier to face when you follow the beautiful and impossible.',delta:1},
 {title:'Call out to the figure waiting beneath the bell tower.',sub:'If this is a dream, you might as well ask it a question.',delta:2},
 {title:'Find a way back to where you woke up.',sub:'You don’t know this place yet. You need to understand it first.',delta:1}
];
function playerPerson(){return {...avatar,style:avatar.hairStyle,coat:'#82687b',accent:'#e3c9b0'}}
function currentChapter(){return route && leads[route]}
function stageForStory(location,time,sceneClass='night-scene'){
 const chars=route?[{person:playerPerson(),id:'player'},{person:currentChapter(),id:route}]:[{person:playerPerson(),id:'player'}];
 setStage({scene:sceneClass,location,time,chars});
}
function routeMenu(){
 stage.classList.add('night-scene');
 const chars=Object.values(leads).map(x=>({person:x,id:x.id}));
 setStage({scene:'night-scene',location:'THE CITY OF VESPER',time:'THREE FATES, ONE THREAD',chars,caption:'<span>THE CITY OF VESPER</span><strong>Every heart has<br>its own gravity.</strong>'});
 panel.innerHTML=`<div class="scene-kicker"><span class="eyebrow">Chapter I · The city of Vesper</span><span class="chapter-count">01 / 04</span></div><h1 class="panel-title">A world that knows<br>your name.</h1><p class="story-text">${originChoice==='isekai'?`The bell tower rings thirteen times. You remember a book, a rainy afternoon, and a life that was yours. Here, in Vesper, ${esc(avatar.name)}, everyone insists you have always belonged.`:`The bell tower rings thirteen times. You know every crooked street in Vesper, every rumor in the market. But tonight, the stars are wrong—and the city seems to be holding its breath.`} A silver thread glimmers around your wrist, then vanishes.</p><p class="story-text">At the moonlit square, three strangers look up at exactly the same moment. Somehow, you know this is where your story turns.</p><div class="section-label">Whose story will you follow?</div><div class="route-cards">${Object.values(leads).map(l=>`<button class="route-card" data-route="${l.id}"><span class="route-avatar" style="background:linear-gradient(155deg,${l.accent}88,${l.coat})">${personSvg(l,{id:'card-'+l.id})}</span><span class="route-info"><b>${l.name}</b><small>${l.role}</small><span class="affinity"><span style="width:${Math.min(100,(affinity[l.id]+2)*18)}%"></span></span></span><span class="route-tag">${l.tag}</span></button>`).join('')}</div><p class="choice-note">Every choice shapes your connection. There are no wrong ways to care.</p>`;
 panel.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{route=b.dataset.route;chapter=0;affinity[route]=affinity[route]||0;screen='route';render()});
}
function prologue(){
 stageForStory(originChoice==='isekai'?'THE BETWEEN':'VESPER · NORTH GATE','THE FIRST NIGHT');
 $('#stage-caption').style.display='none';
 const setup=originChoice==='isekai'?`The last thing you remember is ordinary: rain on glass, a page turning, the soft weight of sleep. Then the world folds like paper. You wake beneath a sky full of unfamiliar stars, a silver bell humming somewhere in the distance.`:`The book in your hands is older than the city. When you open it, the ink rearranges itself into a map of Vesper—your home, though you have never seen this page before. A single silver thread curls around your wrist.`;
 panel.innerHTML=`<div class="scene-kicker"><span class="eyebrow">Prologue · A thread appears</span><span class="chapter-count">00 / 04</span></div><h1 class="panel-title">${originChoice==='isekai'?'The world between.':'The page that changed.'}</h1><p class="story-text">${setup}</p><div class="speaker">A voice from the dark</div><div class="dialogue">“${originChoice==='isekai'?'If you can hear the bell, there is still a way home. If you can see the thread, there may be a reason to stay.':'The old stories are waking, little star. You can close the book—or find out what it wants from you.'}”</div><div class="section-label">What do you do?</div><div class="option-list">${prologueOptions.map((o,i)=>`<button class="story-choice" data-prologue="${i}"><span class="choice-number">0${i+1}</span><span><b>${o.title}</b><small>${o.sub}</small></span></button>`).join('')}</div>`;
 panel.querySelectorAll('[data-prologue]').forEach(b=>b.onclick=()=>{prologueChoice=prologueOptions[+b.dataset.prologue].title;Object.keys(affinity).forEach(k=>affinity[k]+=prologueOptions[+b.dataset.prologue].delta===2?1:0);screen='meeting';render()});
}
function meeting(){
 const lead=currentChapter();
 stageForStory(lead.places[0],lead.role,lead.scene);
 panel.innerHTML=`<div class="scene-kicker"><span class="eyebrow">Chapter I · ${lead.role}</span><span class="chapter-count">01 / 04</span></div><div class="speaker">${lead.name}</div><div class="dialogue">${lead.quote}</div><p class="story-text">${lead.intro} The silver thread at your wrist brightens, connecting you for one breath, then dissolving into moonlight.</p><p class="story-text">${esc(avatar.name)}, the night is young. Where will the two of you go?</p><div class="section-label">Choose your first moment together</div><div class="option-list">${lead.moments.map((m,i)=>`<button class="story-choice" data-meet="${i}"><span class="choice-number">0${i+1}</span><span><b>${m[0]}</b><small>${m[1]}</small></span></button>`).join('')}</div><button class="button-secondary" id="choose-another">← Choose a different fate</button>`;
 panel.querySelectorAll('[data-meet]').forEach(b=>b.onclick=()=>{affinity[route]+=+b.dataset.meet===0?1:2;chapter=0;screen='route';render()});
 $('#choose-another').onclick=()=>{route=null;screen='meeting-select';render()};
}
function sceneChoice(){
 const lead=currentChapter();
 if(chapter>=3){ending();return}
 const names=['A small kindness','What you choose to reveal','A moment just for the two of you'];
 const intro=chapter===0?`The city settles into evening around you. ${lead.name.split(' ')[0]} walks at your side, their usual defenses a little less certain.`:chapter===1?`Night gathers over ${lead.places[chapter]}. A new piece of the silver thread has appeared, glowing faintly between you and ${lead.name.split(' ')[0]}.`:`At ${lead.places[chapter]}, the world seems to pause. Whatever happens next, you want to remember this version of the night.`;
 stageForStory(lead.places[chapter],chapter===0?'LATER THAT EVENING':chapter===1?'AFTER THE LAST BELL':'ONE MOMENT MORE',lead.scene);
 panel.innerHTML=`<div class="scene-kicker"><span class="eyebrow">Chapter ${chapter+2} · ${names[chapter]}</span><span class="chapter-count">0${chapter+2} / 04</span></div><p class="story-text">${intro}</p><div class="speaker">${lead.name}</div><div class="dialogue">${chapter===0?'“People usually ask me about the rumors. You’re the first person tonight who asked how I was.”':chapter===1?'“I thought I had the answer. Then you came along and made every question feel worth keeping.”':'“Whatever tomorrow brings, I’m glad this moment belongs to us.”'}</div><p class="story-text">The silver thread curls softly around your fingers. You feel it waiting—not for the right answer, but for <em>your</em> answer.</p><div class="section-label">${chapter===2?'How will you answer the moment?':'What do you choose?'}</div><div class="option-list">${lead.moments.map((m,i)=>{const copy=chapter===2?lead.final[i]:m[0];return `<button class="story-choice" data-action="${i}"><span class="choice-number">0${i+1}</span><span><b>${copy}</b><small>${chapter===2?'Let the moment speak for itself.':m[1]}</small></span></button>`}).join('')}</div><div class="stats-row"><span>YOUR CONNECTION</span><span>${lead.name.toUpperCase()}</span></div><div class="affinity"><span style="width:${Math.min(100,Math.max(14,affinity[route]*13))}%"></span></div>`;
 panel.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const i=+b.dataset.action;affinity[route]+=i===1?2:1;chapter++;if(chapter===3){showToast('The silver thread between you grows brighter.')}render()});
}
function ending(){
 const lead=currentChapter();
 const score=affinity[route]||0;const bright=score>=7;
 stageForStory('VESPER · UNDER THE STARS','YOUR STORY, STILL UNFOLDING',lead.scene);
 panel.innerHTML=`<div class="scene-kicker"><span class="eyebrow">The end of the beginning</span><span class="chapter-count">04 / 04</span></div><div class="ending-card"><div class="ending-icon">${bright?'✦':'✧'}</div><div class="eyebrow">${bright?'A constellation made for two':'A new star in the sky'}</div><h3>${bright?'Somewhere, together.':'A promise in the making.'}</h3><p>${bright?`The silver thread has become a constellation: two bright points, connected by a line that neither fate nor fear can erase. ${lead.name} reaches for your hand. This time, neither of you lets go.`:`The thread glimmers between you, not binding, just bright with possibility. ${lead.name} smiles and asks what you might discover together tomorrow. You already know you will say yes.`}</p></div><p class="story-text">“${bright?'When the whole world is still a mystery, I’m glad you are the part I know.':'This is not the end of our story. It is the part where we get to write it ourselves.'}”</p><div class="speaker">${lead.name} · ${lead.role}</div><div class="dialogue">You chose to ${prologueChoice.toLowerCase()} and found a heart that met yours halfway. Your journey through Vesper is only just beginning.</div><div class="stats-row"><span>CHAPTERS SHARED</span><span>04 &nbsp;·&nbsp; ${score} HEART MOMENTS</span></div><button class="button-primary" id="restart">BEGIN ANOTHER STORY <span>↻</span></button><div style="height:10px"></div><button class="button-secondary" id="new-route">Choose another heart</button>`;
 $('#restart').onclick=()=>{route=null;chapter=0;affinity={aster:0,ren:0,soren:0};screen='creator';render()};
 $('#new-route').onclick=()=>{route=null;screen='meeting-select';render()};
}
function render(){panel.scrollTop=0;switch(screen){case'creator':creator();break;case'prologue':prologue();break;case'meeting':meeting();break;case'meeting-select':routeMenu();break;case'route':sceneChoice();break;case'ending':ending();break;default:creator()}}
function showToast(message){toast.textContent=message;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2100)}
$('#sound-toggle').onclick=()=>{const button=$('#sound-toggle');const on=button.querySelector('span').textContent==='OFF';button.querySelector('span').textContent=on?'ON':'OFF';button.title=on?'Ambient sound is on':'Ambient sound is off';showToast(on?'Ambient sound enabled':'Ambient sound muted')};
render();

