70:  <div class="creator-block"><div class="section-label">Your character</div><div class="form-row"><div class="field" style="flex:1.35"><label for="hero-name">Name</label><input id="hero-name" maxlength="18" placeholder="A name for your story" value="${esc(avatar.name)}"></div><div class="field"><label for="pronouns">Pronouns</label><select id="pronouns"><option ${avatar.pronouns==='she / her'?'selected':''}>she / her</option><option ${avatar.pronouns==='they / them'?'selected':''}>they / them</option><option ${avatar.pronouns==='he / him'?'selected':''}>he / him</option></select></div></div>
