88: const prologueOptions=[
89:  {title:'Follow the silver moth into the city.',sub:'Some things are easier to face when you follow the beautiful and impossible.',delta:1},
90:  {title:'Call out to the figure waiting beneath the bell tower.',sub:'If this is a dream, you might as well ask it a question.',delta:2},
91:  {title:'Find a way back to where you woke up.',sub:'You don’t know this place yet. You need to understand it first.',delta:1}
