93: function playerPerson(){return {...avatar,style:avatar.hairStyle,coat:'#82687b',accent:'#e3c9b0'}}
94: function currentChapter(){return route && leads[route]}
95: function stageForStory(location,time,sceneClass='night-scene'){
96:  const chars=route?[{person:playerPerson(),id:'player'},{person:currentChapter(),id:route}]:[{person:playerPerson(),id:'player'}];
97:  setStage({scene:sceneClass,location,time,chars});
98: }
99: function routeMenu(){
100:  stage.classList.add('night-scene');
101:  const chars=Object.values(leads).map(x=>({person:x,id:x.id}));
102:  setStage({scene:'night-scene',location:'THE CITY OF VESPER',time:'THREE FATES, ONE THREAD',chars,caption:'<span>THE CITY OF VESPER</span><strong>Every heart has<br>its own gravity.</strong>'});
103:  panel.innerHTML=`<div class="scene-kicker"><span class="eyebrow">Chapter I · The city of Vesper</span><span class="chapter-count">01 / 04</span></div><h1 class="panel-title">A world that knows<br>your name.</h1><p class="story-text">${originChoice==='isekai'?`The bell tower rings thirteen times. You remember a book, a rainy afternoon, and a life that was yours. Here, in Vesper, ${esc(avatar.name)}, everyone insists you have always belonged.`:`The bell tower rings thirteen times. You know every crooked street in Vesper, every rumor in the market. But tonight, the stars are wrong—and the city seems to be holding its breath.`} A silver thread glimmers around your wrist, then vanishes.</p><p class="story-text">At the moonlit square, three strangers look up at exactly the same moment. Somehow, you know this is where your story turns.</p><div class="section-label">Whose story will you follow?</div><div class="route-cards">${Object.values(leads).map(l=>`<button class="route-card" data-route="${l.id}"><span class="route-avatar" style="background:linear-gradient(155deg,${l.accent}88,${l.coat})">${personSvg(l,{id:'card-'+l.id})}</span><span class="route-info"><b>${l.name}</b><small>${l.role}</small><span class="affinity"><span style="width:${Math.min(100,(affinity[l.id]+2)*18)}%"></span></span></span><span class="route-tag">${l.tag}</span></button>`).join('')}</div><p class="choice-note">Every choice shapes your connection. There are no wrong ways to care.</p>`;
104:  panel.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{route=b.dataset.route;chapter=0;affinity[route]=affinity[route]||0;expressions.player='curious';expressions[route]='curious';screen='meeting';render()});
105: }
106: function prologue(){
107:  stageForStory(originChoice==='isekai'?'THE BETWEEN':'VESPER · NORTH GATE','THE FIRST NIGHT');
108:  $('#stage-caption').style.display='none';
109:  const setup=originChoice==='isekai'?`The last thing you remember is ordinary: rain on glass, a page turning, the soft weight of sleep. Then the world folds like paper. You wake beneath a sky full of unfamiliar stars, a silver bell humming somewhere in the distance.`:`The book in your hands is older than the city. When you open it, the ink rearranges itself into a map of Vesper—your home, though you have never seen this page before. A single silver thread curls around your wrist.`;
110:  panel.innerHTML=`<div class="scene-kicker"><span class="eyebrow">Prologue · A thread appears</span><span class="chapter-count">00 / 04</span></div><h1 class="panel-title">${originChoice==='isekai'?'The world between.':'The page that changed.'}</h1><p class="story-text">${setup}</p><div class="speaker">A voice from the dark</div><div class="dialogue">“${originChoice==='isekai'?'If you can hear the bell, there is still a way home. If you can see the thread, there may be a reason to stay.':'The old stories are waking, little star. You can close the book—or find out what it wants from you.'}”</div><div class="section-label">What do you do?</div><div class="option-list">${prologueOptions.map((o,i)=>`<button class="story-choice" data-prologue="${i}"><span class="choice-number">0${i+1}</span><span><b>${o.title}</b><small>${o.sub}</small></span></button>`).join('')}</div>`;
111:  panel.querySelectorAll('[data-prologue]').forEach(b=>b.onclick=()=>{const i=+b.dataset.prologue;prologueChoice=prologueOptions[i].title;expressions.player=['curious','confident','worried'][i];Object.keys(affinity).forEach(k=>affinity[k]+=prologueOptions[i].delta===2?1:0);screen='meeting-select';render()});
112: }
113: function meeting(){
