115:  stageForStory(lead.places[0],lead.role,lead.scene);
116:  panel.innerHTML=`<div class="scene-kicker"><span class="eyebrow">Chapter I · ${lead.role}</span><span class="chapter-count">01 / 04</span></div><div class="speaker">${lead.name}</div><div class="dialogue">${lead.quote}</div><p class="story-text">${lead.intro} The silver thread at your wrist brightens, connecting you for one breath, then dissolving into moonlight.</p><p class="story-text">${esc(avatar.name)}, the night is young. Where will the two of you go?</p><div class="section-label">Choose your first moment together</div><div class="option-list">${lead.moments.map((m,i)=>`<button class="story-choice" data-meet="${i}"><span class="choice-number">0${i+1}</span><span><b>${m[0]}</b><small>${m[1]}</small></span></button>`).join('')}</div><button class="button-secondary" id="choose-another">← Choose a different fate</button>`;
117:  panel.querySelectorAll('[data-meet]').forEach(b=>b.onclick=()=>{const i=+b.dataset.meet;affinity[route]+=i===0?1:2;expressions.player=['happy','curious','shy'][i];expressions[route]=['shy','worried','happy'][i];chapter=0;screen='route';render()});
118:  $('#choose-another').onclick=()=>{route=null;screen='meeting-select';render()};
119: }
120: function sceneChoice(){
121:  const lead=currentChapter();
122:  if(chapter>=3){ending();return}
123:  const names=['A small kindness','What you choose to reveal','A moment just for the two of you'];
124:  const intro=chapter===0?`The city settles into evening around you. ${lead.name.split(' ')[0]} walks at your side, their usual defenses a little less certain.`:chapter===1?`Night gathers over ${lead.places[chapter]}. A new piece of the silver thread has appeared, glowing faintly between you and ${lead.name.split(' ')[0]}.`:`At ${lead.places[chapter]}, the world seems to pause. Whatever happens next, you want to remember this version of the night.`;
125:  stageForStory(lead.places[chapter],chapter===0?'LATER THAT EVENING':chapter===1?'AFTER THE LAST BELL':'ONE MOMENT MORE',lead.scene);
126:  panel.innerHTML=`<div class="scene-kicker"><span class="eyebrow">Chapter ${chapter+2} · ${names[chapter]}</span><span class="chapter-count">0${chapter+2} / 04</span></div><p class="story-text">${intro}</p><div class="speaker">${lead.name}</div><div class="dialogue">${chapter===0?'“People usually ask me about the rumors. You’re the first person tonight who asked how I was.”':chapter===1?'“I thought I had the answer. Then you came along and made every question feel worth keeping.”':'“Whatever tomorrow brings, I’m glad this moment belongs to us.”'}</div><p class="story-text">The silver thread curls softly around your fingers. You feel it waiting—not for the right answer, but for <em>your</em> answer.</p><div class="section-label">${chapter===2?'How will you answer the moment?':'What do you choose?'}</div><div class="option-list">${lead.moments.map((m,i)=>{const copy=chapter===2?lead.final[i]:m[0];return `<button class="story-choice" data-action="${i}"><span class="choice-number">0${i+1}</span><span><b>${copy}</b><small>${chapter===2?'Let the moment speak for itself.':m[1]}</small></span></button>`}).join('')}</div><div class="stats-row"><span>YOUR CONNECTION</span><span>${lead.name.toUpperCase()}</span></div><div class="affinity"><span style="width:${Math.min(100,Math.max(14,affinity[route]*13))}%"></span></div>`;
127:  panel.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const i=+b.dataset.action;affinity[route]+=i===1?2:1;const playerMoods=[['happy','curious','shy'],['worried','happy','curious'],['shy','worried','happy']];const leadMoods=[['happy','annoyed','shy'],['curious','worried','happy'],['happy','shy','worried']];expressions.player=playerMoods[chapter][i];expressions[route]=leadMoods[chapter][i];chapter++;if(chapter===3){showToast('The silver thread between you grows brighter.')}render()});
128: }
129: function ending(){
130:  const lead=currentChapter();
131:  const score=affinity[route]||0;const bright=score>=7;
132:  stageForStory('VESPER · UNDER THE STARS','YOUR STORY, STILL UNFOLDING',lead.scene);
133:  panel.innerHTML=`<div class="scene-kicker"><span class="eyebrow">The end of the beginning</span><span class="chapter-count">04 / 04</span></div><div class="ending-card"><div class="ending-icon">${bright?'✦':'✧'}</div><div class="eyebrow">${bright?'A constellation made for two':'A new star in the sky'}</div><h3>${bright?'Somewhere, together.':'A promise in the making.'}</h3><p>${bright?`The silver thread has become a constellation: two bright points, connected by a line that neither fate nor fear can erase. ${lead.name} reaches for your hand. This time, neither of you lets go.`:`The thread glimmers between you, not binding, just bright with possibility. ${lead.name} smiles and asks what you might discover together tomorrow. You already know you will say yes.`}</p></div><p class="story-text">“${bright?'When the whole world is still a mystery, I’m glad you are the part I know.':'This is not the end of our story. It is the part where we get to write it ourselves.'}”</p><div class="speaker">${lead.name} · ${lead.role}</div><div class="dialogue">You chose to ${prologueChoice.toLowerCase()} and found a heart that met yours halfway. Your journey through Vesper is only just beginning.</div><div class="stats-row"><span>CHAPTERS SHARED</span><span>04 &nbsp;·&nbsp; ${score} HEART MOMENTS</span></div><button class="button-primary" id="restart">BEGIN ANOTHER STORY <span>↻</span></button><div style="height:10px"></div><button class="button-secondary" id="new-route">Choose another heart</button>`;
134:  $('#restart').onclick=()=>{route=null;chapter=0;affinity={aster:0,ren:0,soren:0};screen='creator';render()};
135:  $('#new-route').onclick=()=>{route=null;screen='meeting-select';render()};
136: }
137: function render(){panel.scrollTop=0;switch(screen){case'creator':creator();break;case'prologue':prologue();break;case'meeting':meeting();break;case'meeting-select':routeMenu();break;case'route':sceneChoice();break;case'ending':ending();break;default:creator()}}
138: function showToast(message){toast.textContent=message;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2100)}
139: $('#sound-toggle').onclick=()=>{const button=$('#sound-toggle');const on=button.querySelector('span').textContent==='OFF';button.querySelector('span').textContent=on?'ON':'OFF';button.title=on?'Ambient sound is on':'Ambient sound is off';showToast(on?'Ambient sound enabled':'Ambient sound muted')};
140: render();

