 const charSpecs=people.map((p,i)=>({person:{...p,coat:clothes[0],accent:clothes[1]},id:p.id}));
 const backgrounds={'Moon garden':'garden-scene','Star observatory':'night-scene','Old library':'library-scene','Lantern festival':'garden-scene'};
 setStage({scene:backgrounds[shoot.background],location:shoot.background,time:`${shoot.camera} VIEW · PHOTO STUDIO`,chars:charSpecs,caption:`<span>${shoot.effect.toUpperCase()} · ${shoot.pose.toUpperCase()}</span><strong>${shoot.characters.length===7?'All of Vesper':shoot.characters.length===1?'A moment to keep':'Together, in Vesper.'}</strong>`});
