 panel.innerHTML=`<div class="eyebrow">VESPER · PHOTO STUDIO</div><h1 class="panel-title">Make a memory.</h1><p class="story-text">Set the scene, gather your favorite people, and frame a little moment together.</p><div class="section-label">Who’s in the picture? <small>Choose one, two, or everyone</small></div><div class="shoot-cast">${allCast().map(p=>`<label class="shoot-person ${shoot.characters.includes(p.id)?'selected':''}"><input type="checkbox" data-shoot-person="${p.id}" ${shoot.characters.includes(p.id)?'checked':''}><span class="cast-initial" style="background:${p.coat}">${p.name[0]}</span><span>${p.name}</span></label>`).join('')}</div><div class="shoot-controls"><label>Pose<select data-shoot="pose">${['Together','Side by side','Looking at camera','Candid'].map(o=>`<option ${shoot.pose===o?'selected':''}>${o}</option>`).join('')}</select></label><label>Outfits<select data-shoot="clothes">${['Moonlit formal','Vesper academy','Garden casual','Traveler’s cloak'].map(o=>`<option ${shoot.clothes===o?'selected':''}>${o}</option>`).join('')}</select></label><label>Accessory<select data-shoot="accessory">${['None','Silver hairpin','Flower crown','Moon halo','Round glasses'].map(o=>`<option ${shoot.accessory===o?'selected':''}>${o}</option>`).join('')}</select></label><label>Background<select data-shoot="background">${Object.keys(backgrounds).map(o=>`<option ${shoot.background===o?'selected':''}>${o}</option>`).join('')}</select></label><label>Effect<select data-shoot="effect">${['Soft glow','Stardust','Dream blur','None'].map(o=>`<option ${shoot.effect===o?'selected':''}>${o}</option>`).join('')}</select></label><label>Camera view<select data-shoot="camera">${['Portrait','Wide','Close-up'].map(o=>`<option ${shoot.camera===o?'selected':''}>${o}</option>`).join('')}</select></label></div><div class="shoot-count">${shoot.characters.length} ${shoot.characters.length===1?'character':'characters'} in frame</div>`;
 panel.querySelectorAll('[data-shoot-person]').forEach(input=>input.onchange=()=>{if(input.checked){if(!shoot.characters.includes(input.dataset.shootPerson))shoot.characters.push(input.dataset.shootPerson)}else shoot.characters=shoot.characters.filter(id=>id!==input.dataset.shootPerson);if(!shoot.characters.length){shoot.characters=['aster'];showToast('Choose at least one character for your photo')}photoshoot()});
 panel.querySelectorAll('[data-shoot]').forEach(select=>select.onchange=()=>{shoot[select.dataset.shoot]=select.value;photoshoot()});
}
