.game-nav{display:flex;align-items:center;gap:8px;padding:12px 0 0}.game-nav button{border:1px solid #ffffff25;border-radius:99px;background:#ffffff09;color:#e8dfeb;padding:9px 16px;font:600 10px var(--sans);letter-spacing:.1em;text-transform:uppercase;cursor:pointer;transition:.2s}.game-nav button:hover,.game-nav button.active{background:#d8b77c;color:#241e36;border-color:#d8b77c}.game-nav button span{margin-left:5px}.game-layout{height:min(780px,calc(100vh - 174px))}.home-lead-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px}.home-lead{min-width:0;border:1px solid var(--line);border-radius:4px;padding:7px 4px 9px;background:#fff;color:var(--ink);cursor:pointer;text-align:center;transition:.2s}.home-lead.selected{border-color:var(--plum);box-shadow:0 0 0 2px #6f4a7922;background:#fbf6fb}.home-lead-portrait{height:84px;display:block;overflow:hidden;border-radius:3px;margin-bottom:6px}.home-lead-portrait svg{width:100%;height:100%;object-fit:contain;transform:scale(1.15) translateY(9px)}.home-lead b,.home-lead small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.home-lead b{font:600 9px var(--sans)}.home-lead small{font-size:7px;color:var(--muted);margin-top:3px}.home-actions{display:grid;gap:8px;margin-top:18px}.home-actions .button-secondary{width:100%}.phone-heading{display:flex;justify-content:space-between;align-items:flex-start}.phone-time{font-size:10px;color:var(--muted);padding-top:5px}.phone-app-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:17px 0 20px}.phone-app-grid button{min-height:110px;text-align:left;border:1px solid var(--line);border-radius:7px;background:#fff;padding:15px;color:var(--ink);cursor:pointer}.phone-app-grid button:hover,.phone-recent button:hover{border-color:var(--rose);background:#fffafc}.phone-app-grid i{display:block;font-style:normal;color:var(--plum);font-size:22px;margin-bottom:10px}.phone-app-grid b,.phone-app-grid small{display:block}.phone-app-grid b{font:600 